const { ethers } = require("ethers");
const fs = require("fs");
const crypto = require("crypto");

const RPC_URL = "http://127.0.0.1:8545";

// IMPORTANT:
// Replace this with the NEW contract address after deployment.
const contractAddress = "0x5FC8d32690cc91D4c39d9d3abcBD16989F875707";

// Load the ABI generated by Hardhat.
const artifact = JSON.parse(
    fs.readFileSync(
        "./artifacts/contracts/EvidenceChain.sol/EvidenceChain.json",
        "utf8"
    )
);

const abi = artifact.abi;

const evidenceId = "evidence001";
const caseId = "case001";
const filePath = "./evidence/evidence001.txt";

function calculateHash(filePath) {
    const fileData = fs.readFileSync(filePath);

    return crypto
        .createHash("sha256")
        .update(fileData)
        .digest("hex")
        .toUpperCase();
}

async function main() {

    console.log("Connecting to EvidenceChain...");

    const provider = new ethers.JsonRpcProvider(RPC_URL);

    // Hardhat account 0 = evidence owner
    const owner = await provider.getSigner(0);

    // Hardhat account 1 = another user
    const user = await provider.getSigner(1);

    const ownerAddress = await owner.getAddress();
    const userAddress = await user.getAddress();

    console.log("Owner:", ownerAddress);
    console.log("Test User:", userAddress);
    console.log("Contract:", contractAddress);

    const ownerContract = new ethers.Contract(
        contractAddress,
        abi,
        owner
    );

    const userContract = new ethers.Contract(
        contractAddress,
        abi,
        user
    );


    // ============================================================
    // STEP 1: CALCULATE EVIDENCE HASH
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 1: CALCULATING EVIDENCE HASH");
    console.log("====================================");

    const originalHash = calculateHash(filePath);

    console.log("Evidence ID:", evidenceId);
    console.log("Case ID:", caseId);
    console.log("File:", filePath);
    console.log("SHA-256:", originalHash);


    // ============================================================
    // STEP 2: REGISTER EVIDENCE
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 2: REGISTERING EVIDENCE");
    console.log("====================================");

    const registerTx = await ownerContract.registerEvidence(
        evidenceId,
        caseId,
        originalHash
    );

    await registerTx.wait();

    console.log("Evidence registered successfully.");


    // ============================================================
    // STEP 3: READ EVIDENCE
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 3: READING BLOCKCHAIN RECORD");
    console.log("====================================");

    const evidence = await ownerContract.getEvidence(evidenceId);

    console.log("Evidence ID:", evidence[0]);
    console.log("Case ID:", evidence[1]);
    console.log("Blockchain Hash:", evidence[2]);
    console.log("Registered By:", evidence[3]);
    console.log("Timestamp:", evidence[4].toString());


    // ============================================================
    // STEP 4: CHECK OWNER PERMISSIONS
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 4: CHECKING OWNER PERMISSIONS");
    console.log("====================================");

    const ownerCanView = await ownerContract.canView(
        evidenceId,
        ownerAddress
    );

    const ownerCanDownload = await ownerContract.canDownload(
        evidenceId,
        ownerAddress
    );

    console.log("Owner can view:", ownerCanView);
    console.log("Owner can download:", ownerCanDownload);


    // ============================================================
    // STEP 5: CHECK OTHER USER BEFORE ACCESS
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 5: CHECKING OTHER USER");
    console.log("====================================");

    console.log(
        "User can view:",
        await ownerContract.canView(evidenceId, userAddress)
    );

    console.log(
        "User can download:",
        await ownerContract.canDownload(evidenceId, userAddress)
    );


    // ============================================================
    // STEP 6: GRANT VIEW ACCESS
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 6: GRANTING VIEW ACCESS");
    console.log("====================================");

    const grantViewTx = await ownerContract.grantViewAccess(
        evidenceId,
        userAddress
    );

    await grantViewTx.wait();

    console.log("View access granted.");


    // ============================================================
    // STEP 7: CHECK VIEW ACCESS
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 7: VERIFYING VIEW ACCESS");
    console.log("====================================");

    console.log(
        "User can view:",
        await ownerContract.canView(evidenceId, userAddress)
    );

    console.log(
        "User can download:",
        await ownerContract.canDownload(evidenceId, userAddress)
    );


    // ============================================================
    // STEP 8: USER RECORDS VIEW ACCESS
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 8: RECORDING VIEW ACCESS");
    console.log("====================================");

    const viewTx = await userContract.recordAccess(
        evidenceId,
        "VIEW"
    );

    await viewTx.wait();

    console.log("VIEW access recorded successfully.");


    // ============================================================
    // STEP 9: GRANT DOWNLOAD ACCESS
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 9: GRANTING DOWNLOAD ACCESS");
    console.log("====================================");

    const grantDownloadTx = await ownerContract.grantDownloadAccess(
        evidenceId,
        userAddress
    );

    await grantDownloadTx.wait();

    console.log("Download access granted.");


    // ============================================================
    // STEP 10: CHECK DOWNLOAD ACCESS
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 10: VERIFYING DOWNLOAD ACCESS");
    console.log("====================================");

    console.log(
        "User can download:",
        await ownerContract.canDownload(evidenceId, userAddress)
    );


    // ============================================================
    // STEP 11: USER RECORDS DOWNLOAD ACCESS
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 11: RECORDING DOWNLOAD ACCESS");
    console.log("====================================");

    const downloadTx = await userContract.recordAccess(
        evidenceId,
        "DOWNLOAD"
    );

    await downloadTx.wait();

    console.log("DOWNLOAD access recorded successfully.");


    // ============================================================
    // STEP 12: REVOKE VIEW ACCESS
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 12: REVOKING VIEW ACCESS");
    console.log("====================================");

    const revokeViewTx = await ownerContract.revokeViewAccess(
        evidenceId,
        userAddress
    );

    await revokeViewTx.wait();

    console.log("View access revoked.");

    console.log(
        "User can view:",
        await ownerContract.canView(evidenceId, userAddress)
    );


    // ============================================================
    // STEP 13: REVOKE DOWNLOAD ACCESS
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 13: REVOKING DOWNLOAD ACCESS");
    console.log("====================================");

    const revokeDownloadTx = await ownerContract.revokeDownloadAccess(
        evidenceId,
        userAddress
    );

    await revokeDownloadTx.wait();

    console.log("Download access revoked.");

    console.log(
        "User can download:",
        await ownerContract.canDownload(evidenceId, userAddress)
    );


    // ============================================================
    // STEP 14: VERIFY ORIGINAL EVIDENCE
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 14: VERIFYING ORIGINAL EVIDENCE");
    console.log("====================================");

    const currentHash = calculateHash(filePath);

    const originalVerification = await ownerContract.verifyEvidence(
        evidenceId,
        currentHash
    );

    console.log("Original hash:", currentHash);
    console.log("Blockchain hash:", evidence[2]);
    console.log("Verification:", originalVerification);

    if (originalVerification) {
        console.log("ORIGINAL EVIDENCE IS AUTHENTIC");
    } else {
        console.log("EVIDENCE VERIFICATION FAILED");
    }


    // ============================================================
    // STEP 15: SIMULATE TAMPERING
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 15: SIMULATING TAMPERING");
    console.log("====================================");

    const originalContent = fs.readFileSync(
        filePath,
        "utf8"
    );

    fs.appendFileSync(
        filePath,
        "\nTHIS LINE SIMULATES TAMPERING."
    );

    const tamperedHash = calculateHash(filePath);

    console.log("Tampered hash:", tamperedHash);
    console.log("Blockchain hash:", evidence[2]);


    // ============================================================
    // STEP 16: VERIFY TAMPERED EVIDENCE
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 16: VERIFYING TAMPERED EVIDENCE");
    console.log("====================================");

    const tamperedVerification = await ownerContract.verifyEvidence(
        evidenceId,
        tamperedHash
    );

    console.log("Verification:", tamperedVerification);

    if (!tamperedVerification) {
        console.log("TAMPER DETECTED");
    } else {
        console.log("WARNING: TAMPERING WAS NOT DETECTED");
    }


    // ============================================================
    // STEP 17: RESTORE ORIGINAL FILE
    // ============================================================

    fs.writeFileSync(
        filePath,
        originalContent
    );

    console.log("\nOriginal evidence file restored.");


    // ============================================================
    // STEP 18: ACCESS HISTORY
    // ============================================================

    console.log("\n====================================");
    console.log("STEP 18: ACCESS HISTORY");
    console.log("====================================");

    const history = await ownerContract.getAccessHistory(
        evidenceId
    );

    for (const record of history) {
        console.log(
            "Address:",
            record[0],
            "| Action:",
            record[1],
            "| Timestamp:",
            record[2].toString()
        );
    }


    console.log("\n====================================");
    console.log("ALL TESTS COMPLETED");
    console.log("====================================");
}

main().catch((error) => {
    console.error("\nERROR:");
    console.error(error);
});